import logging
import os
import shutil

import sys
if sys.version_info[0] == 2:
    import subprocess32 as subprocess
else:
    import subprocess

logger = logging.getLogger("taf.rnc.oms.nwi3")
logger.setLevel("DEBUG")

consoleHandler = logging.StreamHandler()
logger.addHandler(consoleHandler)


def get_file_content(file_path):
    """
    Helper function for Pegasus get_* test hierarchies which (because of Pegasus CLI limits) stores obrained value
    inside given file. Function reads the file and returns the value without new line sign. Used precisely to read
    single value from file.

    :param file_path: Absolute path to the file in which obtained value is stored
    :type file_path: str
    :return: Parameter value found in file
    :rtype: str
    """
    with open(file_path, 'r') as f:
        return f.read().rstrip('\n')


class PegasusWrapper(object):
    def __init__(self,
                 exe_path='/opt/Pegasus.RNC/PegasusRCP',
                 exe_flags='-noSplash --launcher.suppressErrors -application pegasus.headless',
                 workspace_path='/tmp/Pegasus/workspace',
                 project_path=os.path.join(os.path.dirname(__file__), 'pegasus_project'),
                 stdout_log_flag='-vmargs -Dpegasus.textualLogger=pegasus.logging.log4j.notpersistent.appender.'
                                 'SysOutAppenderFactory'):
        self.exe_path = exe_path
        self.exe_flags = exe_flags
        self.workspace_path = workspace_path
        self.project_path = project_path
        self.stdout_log_flag = stdout_log_flag

    def get_cli_command(self, th_name, cli_params):
        """
        Wrapper for creating string used as a whole Pegasus CLI command

        :param th_name: Pegasus test hierarchy name
        :type th_name: str
        :param cli_params: Parameters passed to Pegasus test hierarchy gathered within a string
        :type cli_params: str
        :return: Pegasus CLI command which can be launched in shell
        :rtype: str
        """
        base_cmd = self._build_pegasus_base_cli_command()
        return '{base_cmd} -t {th} {params} {log_flag}'.format(base_cmd=base_cmd, th=th_name, params=cli_params,
                                                               log_flag=self.stdout_log_flag)

    def execute_pegasus_cli_command(self, cmd):
        """
        Wrapper for Pegasus CLI command launching. It ensures that whole command will be launched within a shell, with
        finite timeout and RC check. Also put some Pegasus logging into debug log

        :param cmd: Pegasus CLI command to launch
        :type cmd: str
        """
        try:
            process = subprocess.run([cmd], stdout=subprocess.PIPE, shell=True, timeout=300, check=True)
        except subprocess.CalledProcessError as e:
            logger.debug('Command: {cmd}'.format(cmd=e.cmd))
            logger.debug('Process RC: {rc}'.format(rc=e.returncode))
            logger.debug('Output: {stdout}'.format(stdout=e.stdout))
            raise e
        else:
            logger.debug('Command: {cmd}'.format(cmd=process.args))
            logger.debug('Output: {stdout}'.format(stdout=process.stdout))
        finally:
            shutil.rmtree('/tmp/Pegasus/', ignore_errors=True)

    def build_parameters_string_for_pegasus_set_operations(self, params_to_change):
        """
        Helper function which transfer the dictionary of params to change (kwargs) into fancy string mandatory in
        Pegasus CLI set_* test hierarchies.

        :param params_to_change: OMS parameters to change in dictionary manner
        :type params_to_change: dict
        :return: String with param and values to change in Pegasus CLI manner
        :rtype: str
        """
        params_with_values = ''
        for param, value in params_to_change.items():
            params_with_values = params_with_values + '{param}:{value}\n'.format(param=param, value=value)
        return "'{params_with_values}'".format(params_with_values=params_with_values)

    def _build_pegasus_base_cli_command(self):
        return '{command} {exe_flags} -data {workspace} -p {project}'.format(command=self.exe_path,
                                                                             exe_flags=self.exe_flags,
                                                                             workspace=self.workspace_path,
                                                                             project=self.project_path)
